import json
from pathlib import Path
A=[]
def add(i,s,q,m,**kw):A.append(dict(index=i,classification='material' if i not in (16,18) else 'context',summary=s,rows=[dict(quote=q,model_quantity=m,stage='recognized',issuer_treatment=s,**kw)]))
add(12,'Dette 2024 : convertibles 2029 et 2031 distinctes des anciennes dettes éteintes ; le put du porteur au 15 décembre 2027 peut avancer le remboursement des 2031. PIK historiques effectivement payés en actions en juin 2024 puis conversion obligatoire juillet : ne pas les présenter comme PIK courants. Les anciens prêts minage, roll-up et garanties de sortie éteints ne sont pas de nouveaux financements HPC.','Noteholders may require the Company to repurchase their 2031 Convertible Notes upon the occurrence of a “Fundamental Change” (as defined in the 2031 Convertible Notes Indenture) or on December 15, 2027.','convertible_holder_put_earlier_than_stated_maturity',measurement_basis='2031_notes_holder_put_Dec2027;not_automatic_cash_payment')
A[-1]['rows'].append(dict(quote='The Company exercised its option to make the June 15, 2024 interest payment 6% in cash for approximately $6.0 million and 6% in stock and issued 881,610 shares of its New Common Stock to the holders of the New Secured Convertible Notes on that date for total interest expense of approximately $9.8 million.',model_quantity='historical_PIK_interest_paid_in_shares',stage='settled',event_date='2024-06-15',measurement_basis='historical_actual_payment;instrument_converted_July2024;not_current_BDC_PIK_share'))
add(13,'T1 2025 : revenu différé 60,9 M au bilan contre 18,1 M fin 2024, sans transformer la variation en encaissement brut. Colocation reste ASC 842, énergie brute variable ; RPO minage seulement. Crypto détenue pour vente future distincte de cash libre, juste valeur en résultat.','Advanced payments are typically recognized in the following month for hosted mining services and are generally recognized within 30 months of license order commencement for colocation services.','customer_advance_revenue_recognition_timing',measurement_basis='March2025_deferred_revenue_stock;not_cash_receipt_rollforward')
add(14,'Engagements construction au 31 mars 2025 : 1,25 Md brut, 906,2 M pass-through facturé au client, 314,8 M à financer par prépaiements de loyers ; horizon 12–24 mois. Le client reste anonyme dans ce bloc. Les composantes de remboursement ne prouvent pas des fonds déjà reçus et ne s’ajoutent pas au total brut. Litiges historiques sans nouveau montant de perte estimable.','Of this amount, $906.2 million will be passed through to the Company’s customer as invoiced and $314.8 million will be funded by the customer as prepaid base license fees for the Collocation segment.','customer_financed_construction_commitment_components',counterparty_evidence='anonymous',measurement_basis='March2025_components_of_gross_1.25bn;not_cash_received')
add(15,'T1 2025 restaté : HPC renommé Colocation, sans nouveau segment économique. Client J anonyme : 100 % du revenu segment, non attribué à CoreWeave. Résultat avant impôt positif dominé par gain non monétaire des warrants/CVR, malgré perte opérationnelle ; ne pas interpréter le résultat comme cash ou marge HPC.','During fiscal year 2024, our “Colocation” segment was referred to as “HPC Hosting.”','HPC_segment_name_change',basis_break=True,recast_cause='presentation_reclassification')
add(16,'RSU/MSU de rémunération T1 2025 : conditions de service/cours et charges dont une partie capitalisée. Reprise de charges T1 2024 liée à forfaitures, pas nouvelle recette ; aucune remise de warrants à un client identifiée dans ce bloc.','The three months ended March 31, 2024, includes the reversal of stock-based compensation expense due to $6.1 million in forfeitures incurred during the period.','employee_share_compensation_reversal',measurement_basis='historical_staff_compensation;not_customer_consideration')
add(17,'Baux T1 2025 : 10 Md de loyers futurs à recevoir sur baux non commencés EXCLUS du tableau des baux commencés. Ce sont des entrées contractuelles attendues, pas des ventes reconnues ni obligations du locataire Core. Valeurs locatives actualisées et paiements bruts côté preneur restent distincts.','Operating lease payments expected to be received excludes $10.0 billion in total future noncancellable minimum lease payments for operating leases that have not yet commenced at March 31, 2025, which have lease terms of 12 years from commencement.','lessor_uncommenced_future_rent_inflows',measurement_basis='March2025;inflows_not_contractual_outflows_or_recognized_revenue')
add(18,'Tableau dette T1 2025 : face 1,118098 Md, décotes distinctes, coût effectif des convertibles supérieur au coupon. Les maturités montrent zéro convertible courant mais ne remplacent pas la clause de put anticipé figurant en note annuelle. Pas de nouveau financeur nommé ou de défaut divulgué ici.','Maturities on convertible and other notes payable, gross of unamortized discounts, are as follows (in thousands):','debt_maturity_reporting_basis',measurement_basis='March2025_gross_principal_schedule;not_carrying_value_or_put_adjusted_cash_schedule')
add(19,'T1 2025 : diminution 634,3 M de la juste valeur des warrants et hausse 12,8 M des CVR enregistrées en résultat. Ce gain ne correspond pas à du cash opérationnel. Les valeurs de marché des convertibles sont informatives, distinctes du remboursement et de la comptabilisation au coût amorti ; aucune dépréciation non financière sur le trimestre décrit.','During the three months ended March 31, 2025, a decrease in fair value of Warrants of $634.3 million was included in Change in fair value of warrant and contingent value rights on the Company’s condensed consolidated statements of operations.','warrant_fair_value_income_effect',judgment_sensitive=True,measurement_basis='March2025_non_cash_fair_value_gain;not_HPC_margin')
